using HRIS.Api.Controllers; using HRIS.Api.DTOs.Parking; using HRIS.Api.Exceptions; using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace HRIS.Api.Pages.Parking; [Authorize(AuthenticationSchemes="Cookies")] public class IndexModel:PageModel { private readonly IParkingService _service; public IndexModel(IParkingService service)=>_service=service; public List<VehicleTypeOption> VehicleTypes{get;set;}=new(); public List<ParkingResponseDto> Items{get;set;}=new(); public bool CanManage{get;set;} public async Task OnGetAsync(){var a=User.ToUserContext();CanManage=a.IsHrOrSupport;VehicleTypes=await _service.GetVehicleTypesAsync();Items=await _service.GetAsync(a);} public async Task<IActionResult> OnPostCreateAsync(int vehicleTypeId,string plateNumber){try{await _service.CreateAsync(new ParkingCreateDto{VehicleTypeId=vehicleTypeId,PlateNumber=plateNumber},User.ToUserContext());TempData["Success"]="Registrasi parkir diajukan.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException){TempData["Error"]=ex.Message;}return RedirectToPage();} public async Task<IActionResult> OnPostStatusAsync(int id,string status){try{await _service.UpdateStatusAsync(id,status,User.ToUserContext());TempData["Success"]="Status parkir diperbarui.";}catch(Exception ex)when(ex is BadRequestException or ForbiddenException or NotFoundException){TempData["Error"]=ex.Message;}return RedirectToPage();} }
